using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.TKT.DocumentosComentarioTicket;namespace GraphApi.Services.TKT.DocumentosComentarioTicket{    public class DocumentosComentarioTicketService : IDocumentosComentarioTicketService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public DocumentosComentarioTicketService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadDocumentosComentarioTicket>> GetDocumentosComentarioTickets(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM tkt.DocumentosComentarioTicket (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadDocumentosComentarioTicket>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetDocumentosComentarioTicketsDynamic(            int? documentoComentarioTicketID,            int? comentarioTicketID,            int? documentoID,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "DocumentoComentarioTicketID, ComentarioTicketID, DocumentoID, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM tkt.DocumentosComentarioTicket (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (documentoComentarioTicketID.HasValue)            {                vSql.Append(" AND DocumentoComentarioTicketID = @DocumentoComentarioTicketID");                vParameters.Add("DocumentoComentarioTicketID",documentoComentarioTicketID);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadDocumentosComentarioTicket> CreateDocumentosComentarioTicket(clCreateDocumentosComentarioTicket objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO tkt.DocumentosComentarioTicket                (ComentarioTicketID, DocumentoID, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@ComentarioTicketID, @DocumentoID, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.ComentarioTicketID,                objInput.DocumentoID,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT DocumentoComentarioTicketID, ComentarioTicketID, DocumentoID, bEliminado                FROM tkt.DocumentosComentarioTicket (NOLOCK)                WHERE DocumentoComentarioTicketID = @DocumentoComentarioTicketID;";            var vReadParams = new { DocumentoComentarioTicketID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadDocumentosComentarioTicket>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el DocumentosComentarioTicket con ID {vNewId}.");            return vCreated;        }        public async Task<clReadDocumentosComentarioTicket?> UpdateDocumentosComentarioTicket(clUpdateDocumentosComentarioTicket objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("DocumentoComentarioTicketID", objInput.DocumentoComentarioTicketID);            if (objInput.ComentarioTicketID != null)            {                vSets.Add("ComentarioTicketID = @ComentarioTicketID");                vParameters.Add("ComentarioTicketID", objInput.ComentarioTicketID);            }            if (objInput.DocumentoID != null)            {                vSets.Add("DocumentoID = @DocumentoID");                vParameters.Add("DocumentoID", objInput.DocumentoID);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE tkt.DocumentosComentarioTicket                SET {vSetClause}                WHERE DocumentoComentarioTicketID = @DocumentoComentarioTicketID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT DocumentoComentarioTicketID, ComentarioTicketID, DocumentoID, bEliminado                FROM tkt.DocumentosComentarioTicket (NOLOCK)                WHERE DocumentoComentarioTicketID = @DocumentoComentarioTicketID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadDocumentosComentarioTicket>(sSelect, new {  objInput.DocumentoComentarioTicketID });        }        public async Task<bool> DeleteDocumentosComentarioTicket(int nDocumentosComentarioTicketID)        {            const string sSql = @"                DELETE FROM tkt.DocumentosComentarioTicket                WHERE DocumentoComentarioTicketID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nDocumentosComentarioTicketID });            return vAffected > 0;        }    }}